function renderCoreCourseMap(filter=''){
  const root=document.getElementById('coreCourseChapters');if(!root)return;
  const q=String(filter||'').trim().toLowerCase();
  const focusAId=courseAContinueId();
  const focusChapter=CORE_A_TOPIC_MAP?.[focusAId]?.chapter||CORE_A_CURRICULUM.find(x=>x.id===focusAId)?.chapter||null;
  const byChapter={};CORE_A_CURRICULUM.forEach(t=>(byChapter[t.chapter]??=[]).push(t));
  let output='';
  CORE_A_CHAPTERS.forEach(ch=>{
    const all=byChapter[ch]||[];
    const rows=all.filter(t=>!q||`${t.code} ${t.title} ${t.chapterTitle} ${t.lead} ${t.points.join(' ')}`.toLowerCase().includes(q));
    if(q&&!rows.length)return;

    const lessonDone=all.filter(t=>(profile.lessonProgress?.[t.id]||0)>=100).length;
    const settled=all.filter(t=>['stable','master'].includes(coreTopicLearningState(t.id).key)).length;
    const pct=Math.round(all.reduce((s,t)=>s+(profile.lessonProgress?.[t.id]||0),0)/Math.max(1,all.length));

    output+=`<section class="core-chapter ${q?'open':''}">
      <div class="core-chapter-head" data-core-chapter="${ch}">
        <div class="core-chapter-no">${ch}</div>
        <div>
          <div class="core-chapter-title">${escapeHtml(all[0].chapterTitle)}</div>
          <div class="core-chapter-meta">教材 ${lessonDone}/${all.length}・定着 ${settled}/${all.length}</div>
        </div>
        <div class="core-chapter-progress"><b>${pct}%</b><span>${q?'検索結果 '+rows.length+'件':'教材進捗'}</span></div>
      </div>
      <div class="core-chapter-body">
        ${coreChapterGuideView(ch)}
        ${rows.map(t=>{
          const p=profile.lessonProgress?.[t.id]||0,state=coreTopicLearningState(t.id);
          return `<div class="core-topic-row ${p>=100?'done':''} ${t.id===focusAId?'course-next-topic':''} learning-${state.key}" data-core-lesson="${t.id}">
            <div class="core-topic-code">${t.code}</div>
            <div>
              <div class="core-topic-name">${t.id===focusAId?'<span class="course-next-badge">未完了</span> ':''}${learningHtml(t.title)}</div>
              <div class="core-topic-sub">${escapeHtml(t.lead.slice(0,74))}${t.lead.length>74?'…':''}</div>
              <div class="core-topic-qcount">テーマ演習 ${state.total||CORE_A_TOPIC_PRACTICE_COUNTS[t.id]||3}問${state.attempted?`・回答 ${state.attempted}/${state.total}`:''}</div>
            </div>
            <div class="core-topic-pct state-${state.key}">${masteryRecoveryInfo(t.id)?'↩ 復帰中・':''}${state.label}</div>
          </div>`;
        }).join('')}
        <button class="core-chapter-check" data-core-chapter-quiz="${ch}">第${ch}章：全${all.length}テーマ＋比較を12問で確認 →</button>
      </div>
    </section>`;
  });
  root.innerHTML=output||'<div class="empty">該当するテーマがありません。</div>';
}

function renderLearningEntry(){
  const card=document.getElementById('courseNextCard');
  const title=document.getElementById('courseNextTitle');
  const desc=document.getElementById('courseNextDesc');
  const kicker=document.getElementById('courseNextKicker');
  const icon=document.getElementById('courseNextIcon');
  const action=document.getElementById('courseNextAction');
  if(!card||!title||!desc||!kicker||!icon||!action)return;

  const aDone=CORE_A_IDS.filter(id=>(profile.lessonProgress?.[id]||0)>=100).length;
  const algoDone=B_EXERCISES.filter(x=>(profile.bProgress?.[x.id]||0)>=100).length;
  const secDone=SECURITY_SCENARIOS.filter(x=>(profile.securityBProgress?.[x.id]||0)>=100).length;
  const aMeta=document.getElementById('courseATabMeta');if(aMeta)aMeta.textContent=`教材 ${aDone} / ${CORE_A_IDS.length}`;
  const bMeta=document.getElementById('courseBTabMeta');if(bMeta)bMeta.textContent=`基礎演習 ${algoDone+secDone} / ${B_EXERCISES.length+SECURITY_SCENARIOS.length}`;

  const days=examDaysRemaining();
  const ui=readUiState();
  const resumeId=ui.lessonId&&CORE_A_IDS.includes(ui.lessonId)&&(profile.lessonProgress?.[ui.lessonId]||0)<100?ui.lessonId:null;
  if(resumeId&&!(days!=null&&days>=0&&days<=3)){
    const lesson=LESSONS[resumeId];
    kicker.textContent='前回の続き';icon.textContent='📘';
    title.textContent=lesson.title;
    desc.textContent=`${lesson.skill}。前回開いていたテーマから再開します。`;
    action.disabled=false;action.textContent='続きから再開 →';action.onclick=()=>resumeCourseLesson(resumeId);
    setCourseSubject('A',false);
    updateCourseBRecommendedCard(null);
    renderCoreCourseMap(document.getElementById('coreCourseSearch')?.value||'');
    return;
  }

  const rec=getDailyRecord();
  const tasks=ensureTodayPlanSnapshot();
  const pendingLearn=tasks.find(t=>dailyTaskSlot(t)==='learn'&&!dailyTaskDone(rec,t));
  if(pendingLearn){
    kicker.textContent='今日の学習枠';
    icon.textContent=pendingLearn.icon||'📚';
    title.textContent=pendingLearn.title;
    desc.textContent=`${pendingLearn.minutes}分の予定。今日の計画に沿ってここから始めます。`;
    action.disabled=false;action.textContent='今日の学習を始める →';action.onclick=()=>launchDailyTask(pendingLearn);
    const isB=pendingLearn.type==='subjectB'||(pendingLearn.type==='finalFocus'&&pendingLearn.focus?.kind==='subjectB');
    if(isB){
      const b=pendingLearn.type==='subjectB'?{mode:pendingLearn.bmode,id:pendingLearn.bid}:pendingLearn.focus?.b;
      setCourseSubject('B',false);updateCourseBRecommendedCard(b?.mode);
    }else{
      setCourseSubject('A',false);updateCourseBRecommendedCard(null);
    }
    renderCoreCourseMap(document.getElementById('coreCourseSearch')?.value||'');
    return;
  }

  kicker.textContent=(days!=null&&days>=0&&days<=3)?'今日の方針':'今日の学習枠';
  icon.textContent='✅';
  title.textContent=(days!=null&&days>=0&&days<=3)?'新しい教材を増やさず、今日の計画を優先':'今日の教材・基礎学習は完了';
  desc.textContent=(days!=null&&days>=0&&days<=3)?'試験直前は復習と短い確認を優先します。教材一覧は参照できますが、追加学習はおすすめしません。':'追加で進める必要はありません。復習や演習など、今日の残りはホームから確認できます。';

