      minutes:total
    }];
  }

  if(days===1){
    return [
      {
        type:'taperReview',icon:'🧠',bg:'green',
        title:'前日の復習 5問まで',
        desc:routes?`復習ルート ${routes}件から優先`:due?`期限/低保持 ${due}問から最大5問`:`「${weak}」を最大5問だけ確認`,
        minutes:alloc.review
      },
      {
        type:'warmup',icon:'🌙',bg:'yellow',
        title:'軽いウォームアップ 3問',
        desc:'解き慣れた既習問題だけで感覚を確認。新しい範囲は増やしません。',
        minutes:alloc.boss
      }
    ].filter(t=>t.minutes>0);
  }

  const focus=taperFocusRecommendation(days);
  const tasks=[
    {
      type:'taperReview',icon:'🧠',bg:'green',
      title:days<=3?'直前復習 5問':'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`期限/低保持 ${due}問を優先`:`今日の期限はなし。「${weak}」を維持`,
      minutes:alloc.review
    },
    {
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:alloc.lesson,focus
    }
  ];

  if(days>=4&&alloc.subjectB>=10){
    const b=nextBChoice(alloc.subjectB);
    tasks.push({
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`科目B：${b.title}`:b.mode==='security'?`科目B：${b.title}`:b.title,
      desc:'長時間の総合実戦ではなく、短い既習演習を1つ',
      minutes:alloc.subjectB,bmode:b.mode,bid:b.id
    });
  }else if(alloc.subjectB>0){
    tasks[1].minutes+=alloc.subjectB;
  }

  tasks.push({
    type:'boss',icon:'👑',bg:'yellow',
    title:'直前総合チェック',
    desc:'判断3問＋適用2問。新規知識ではなく、使えるかだけを5問で確認。',
    minutes:alloc.boss
  });
  return tasks.filter(t=>t.minutes>0);
}

function chooseExamWarmupQuestions(n=3){
  ensureQuestionProfile();
  const attempted=QUESTION_BANK.filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0&&!questionHasActiveJourney(q.id));
  const stable=attempted.filter(q=>{
    const r=memoryRetention(profile.qStats[q.id]);
    return r!=null&&r>=80;
  });
  const source=stable.length?stable:attempted;
  const selected=[],usedCats=new Set(),used=new Set();
  const ranked=shuffled(source).sort((a,b)=>{
    const ar=memoryRetention(profile.qStats[a.id])??0,br=memoryRetention(profile.qStats[b.id])??0;
    const cognitiveRank={'想起':0,'適用':1,'判断':2};
    const difficultyRank={'基礎':0,'標準':1,'実戦':2};
    const as=(cognitiveRank[a.cognitiveLevel]??2)*20+(difficultyRank[a.difficulty]??1)*8+Math.abs(ar-90);
    const bs=(cognitiveRank[b.cognitiveLevel]??2)*20+(difficultyRank[b.difficulty]??1)*8+Math.abs(br-90);
    // 当日は「できる問題を軽く解く」ことが目的。想起・基礎を優先し、難しい判断問題は最後にする。
    return as-bs;
  });
  for(const q of ranked){
    if(selected.length>=n)break;
    if(usedCats.has(q.cat))continue;
    selected.push(q);used.add(q.id);usedCats.add(q.cat);
  }
  for(const q of ranked){
    if(selected.length>=n)break;
    if(used.has(q.id))continue;
    selected.push(q);used.add(q.id);
  }
  // 学習履歴が全くない特殊ケースだけ、基礎の想起問題を最小限使う。
  if(selected.length<n){
    shuffled(QUESTION_BANK.filter(q=>q.difficulty==='基礎'&&q.cognitiveLevel==='想起'&&!used.has(q.id)))
      .slice(0,n-selected.length).forEach(q=>selected.push(q));
  }
  return selected.slice(0,n);
}

