function setCourseSubject(subject,save=true){
  activeCourseSubject=subject==='B'?'B':'A';
  const a=document.getElementById('subjectACoursePanel');
  const b=document.getElementById('subjectBCoursePanel');
  const showA=activeCourseSubject==='A';
  if(a){
    a.hidden=!showA;
    a.classList.toggle('course-panel-hidden',!showA);
    a.setAttribute('aria-hidden',String(!showA));
  }
  if(b){
    b.hidden=showA;
    b.classList.toggle('course-panel-hidden',showA);
    b.setAttribute('aria-hidden',String(showA));
  }
  document.querySelectorAll('[data-course-subject]').forEach(btn=>{
    const selected=btn.dataset.courseSubject===activeCourseSubject;
    btn.classList.toggle('active',selected);
    btn.setAttribute('aria-selected',String(selected));
    btn.tabIndex=selected?0:-1;
  });
  if(save){
    profile.settings=profile.settings||{};
    profile.settings.lastCourseSubject=activeCourseSubject;
    saveProfile();
  }
}

