function finalFocusRecommendation(status=courseMasteryStatus()){
  const days=examDaysRemaining();
  const urgentPhase=days!=null&&days>=0&&days<=14;
  const deepTaper=days!=null&&days>=0&&days<=3;
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;

  if(days===0){
    return {kind:'warmup',icon:'☀️',title:'今日は3問だけ確認',desc:'新規教材も長時間模試も追加しません。既習3問で感覚だけ整えます。',button:'ウォームアップ3問'};
  }
  if(days===1){
    if(routes||due)return {kind:'review',icon:'🧠',title:'前日は復習だけ',desc:`復習ルート ${routes}件・期限/低保持 ${due}問。長時間模試や新規教材は追加しません。`,button:'5問まで確認'};
    return {kind:'warmup',icon:'🌙',title:'前日は軽い確認だけ',desc:'既習3問だけ確認し、新しい範囲は増やしません。',button:'ウォームアップ3問'};
  }

  if((routes||due)&&((urgentPhase)||(status.mem.due>10))){
    return {kind:'review',icon:'🧠',title:'最優先：復習待ちを解消',desc:`復習ルート ${routes}件・期限/低保持 ${due}問。判断問題を優先して戻します。`,button:deepTaper?'5問まで確認':'復習を始める'};
  }

  // 残り3日以内は、未完了教材があっても新規範囲を広げない。
  if(!deepTaper&&status.lessonDone<130){
    const lesson=nextLessonChoice();
    return {kind:'lesson',icon:'📘',title:'未完了教材を埋める',desc:`残り ${130-status.lessonDone}テーマ。弱い分野から未完了教材を進めます。`,button:'次の教材へ',lessonId:lesson.id};
  }

  if(status.bTraining<90&&!urgentPhase){
    const b=nextBChoice(20);
    return {kind:'subjectB',icon:'💻',title:'科目Bの基礎演習を完成',desc:`科目B学習 ${status.bTraining}% 。未完了のアルゴリズム/セキュリティを優先します。`,button:'科目Bを続ける',b};
  }

  if(deepTaper){
    const weakEvidence=categoryCognitiveEvidence(status.weakest[0]);
    if(Number(status.weakest[1])<70){
      const level=weakEvidence.weakest.level;
      return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${level}を短く補強`,desc:'残り3日以内は新規教材やフル模試ではなく、既習の最弱思考を10問だけ確認します。',button:`${level}を10問`,cat:status.weakest[0],level};
    }
    if(status.bTraining<90){
      const b=nextBChoice(10);
      return {kind:'subjectB',icon:'💻',title:'科目Bを1セットだけ確認',desc:'100分総合実戦は追加せず、既存の短い演習を一つ確認します。',button:'科目Bを確認',b};
    }
    const chapter=nextReadyUnpassedChapter();
    if(chapter){
      return {kind:'chapter',icon:'🧩',title:`第${chapter.ch}章を短く統合確認`,desc:'学習済みの章だけを確認します。未学習範囲は混ぜません。',button:`第${chapter.ch}章を確認`,chapter:chapter.ch};
    }
    const x=nextMasterTopicCandidate();
    if(x&&(profile.lessonProgress?.[x.topic.id]||0)>=100){
      return {kind:'topic',icon:'⭐',title:`${x.topic.title}を維持`,desc:'既習テーマの保持を整えます。新しい知識は増やしません。',button:'テーマ演習',topicId:x.topic.id};
    }
    return {kind:'warmup',icon:'✅',title:'既習3問だけ確認',desc:'ここからは仕上がりを崩さないことを優先します。',button:'ウォームアップ3問'};
  }

  if(urgentPhase&&!status.aMock.passed){
    return {kind:'aMock',icon:'🏁',title:'科目Aを本番時間で確認',desc:'フル模試2回の安定条件が未達です。90分を確保できる日に本番型で確認します。',button:'フル模試90分を始める',long:true};
  }

  if(urgentPhase&&!status.bFinal.passed){
