    st.attempts++;
    st.correct++

function registerReviewJourney(q,source='practice'){
  const id=q?.sourceId||q?.id;if(!id)return null;
  const base=questionById(id)||q;
  const old=profile.reviewJourneys[id]||{};
  const lessonId=lessonForQuestion(base);
  const wasStable=old.stage==='stable';
  profile.reviewJourneys[id]={
    ...old,id,cat:base.cat,concept:base.concept,lessonId,
    stage:wasStable?(lessonId?'relearn':'verify'):(old.stage|| (lessonId?'relearn':'verify')),
    misses:(old.misses||0)+1,lastWrong:localDateISO(0),source,
    due:profile.qStats?.[id]?.due||localDateISO(1),completedAt:wasStable?null:old.completedAt
  };
  saveProfile();
  return profile.reviewJourneys[id];
}

function markJourneyAnswer(id,firstTryCorrect){
  const j=journeyFor(id);if(!j)return;
  if(firstTryCorrect){
    if(j.stage==='verify'){j.stage='spaced';j.verifyDone=localDateISO(0);j.due=profile.qStats?.[id]?.due||localDateISO(2);}
    else if(j.stage==='spaced'){j.stage='stable';j.spacedDone=localDateISO(0);j.completedAt=localDateISO(0);}
  }else{j.stage='verify';j.due=localDateISO(1);}
  saveProfile();
}

function renderAnalyticsJourneys(){
  const counts=analyticsJourneyCounts();
  document.getElementById('analyticsStableTotal').textContent=counts.stable;
  const stage=document.getElementById('analyticsJourneyStages');if(stage)stage.innerHTML=`<div class="analytics-stage"><b>${counts.relearn}</b><span>教材</span></div><div class="analytics-stage"><b>${counts.verify}</b><span>類題</span></div><div class="analytics-stage"><b>${counts.spaced}</b><span>後日待ち</span></div><div class="analytics-stage"><b>${counts.stable}</b><span>定着</span></div>`;
  const stable=Object.values(profile.reviewJourneys||{}).filter(j=>j.stage==='stable').sort((a,b)=>String(b.completedAt||'').localeCompare(String(a.completedAt||''))).slice(0,6);
  const list=document.getElementById('analyticsStableList');if(list)list.innerHTML=stable.length?stable.map(j=>`<div class="analytics-stable-item"><b>${escapeHtml(j.concept)}</b><span>${escapeHtml(j.completedAt||'定着')}</span></div>`).join(''):'<div class="analytics-format-empty">まだ定着まで完了した復習ルートはありません。</div>';
}

function activeReviewJourneys(){
  return Object.values(profile.reviewJourneys||{}).filter(j=>j.stage!=='stable').sort((a,b)=>{
    const rank=j=>j.stage==='spaced'?(j.due<=localDateISO(0)?-1:9):j.stage==='relearn'?0:j.stage==='verify'?1:8;
    if(rank(a)!==rank(b))return rank(a)-rank(b);
    return String(b.lastWrong||'').localeCompare(String(a.lastWrong||''));
  });
}

function buildTaperTodayTasks(days,total){
  const alloc=taperTaskAllocation(total,days);
  const routes=actionableReviewJourneys().length,due=dueQuestions().length;
  const weak=weakestSkill();

  if(days<=0){
    return [{
      type:'warmup',icon:'☀️',bg:'yellow',
      title:'受験前ウォームアップ 3問',
      desc:'既習問題を中心に3問だけ確認。新規教材・長時間模試・追い込みは行いません。',
      minutes:total
    }];
  }

  if(days===1){
    return [
      {
        type:'taperReview',icon:'🧠',bg:'green',
        title:'前日の復習 5問まで',
        desc:routes?`復習ルート ${routes}件から優先`:due?`期限/低保持 ${due}問から最大5問`:`「${weak}」を最大5問だけ確認`,
        minutes:alloc.review
      },
      {
        type:'warmup',icon:'🌙',bg:'yellow',
        title:'軽いウォームアップ 3問',
        desc:'解き慣れた既習問題だけで感覚を確認。新しい範囲は増やしません。',
        minutes:alloc.boss
      }
    ].filter(t=>t.minutes>0);
  }

  const focus=taperFocusRecommendation(days);
  const tasks=[
    {
      type:'taperReview',icon:'🧠',bg:'green',
      title:days<=3?'直前復習 5問':'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`期限/低保持 ${due}問を優先`:`今日の期限はなし。「${weak}」を維持`,
      minutes:alloc.review
    },
    {
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:alloc.lesson,focus
    }
  ];

  if(days>=4&&alloc.subjectB>=10){
    const b=nextBChoice(alloc.subjectB);
    tasks.push({
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`科目B：${b.title}`:b.mode==='security'?`科目B：${b.title}`:b.title,
      desc:'長時間の総合実戦ではなく、短い既習演習を1つ',
      minutes:alloc.subjectB,bmode:b.mode,bid:b.id
    });
  }else if(alloc.subjectB>0){
    tasks[1].minutes+=alloc.subjectB;
  }

  tasks.push({
    type:'boss',icon:'👑',bg:'yellow',
    title:'直前総合チェック',
    desc:'判断3問＋適用2問。新規知識ではなく、使えるかだけを5問で確認。',
    minutes:alloc.boss
  });
  return tasks.filter(t=>t.minutes>0);
}

